pragma solidity ^0.8.28;

import {Test, console2} from "forge-std/Test.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {FeeDistributor} from "../../src/fees/FeeDistributor.sol";
import {ZENTBuyback} from "../../src/ZENTBuyback.sol";
import {ZENT} from "../../src/ZENT.sol";
import {ZENTStaking} from "../../src/staking/ZENTStaking.sol";

contract MockERC20 is ERC20 {
    constructor(string memory n, string memory s) ERC20(n, s) {}
    function mint(address to, uint256 amount) external { _mint(to, amount); }
}

/// @notice ACCOUNTING lens (L2) PoC — conservation-law violations.
contract AccountingL2PoC is Test {
    MockERC20 internal wbtc;
    ZENT internal zent;
    FeeDistributor internal distributor;
    ZENTStaking internal staking;

    address internal governor = makeAddr("governor");
    address internal gpEngine = makeAddr("gpEngine");
    address internal insurance = makeAddr("insurance");
    address internal treasury = makeAddr("treasury");
    address internal vault = makeAddr("vault");

    function _setupFeeDistributor() internal {
        wbtc = new MockERC20("WBTC", "WBTC");
        zent = new ZENT();
        distributor = new FeeDistributor(address(wbtc), address(zent), governor, gpEngine, insurance, treasury);
        wbtc.mint(vault, 1_000_000_000);
    }

    /// INVARIANT: comment at FeeDistributor.sol:42 — "Pool balances held by this contract":
    /// sum(pools) == asset.balanceOf(this)
    function test_poc_1_gpPoolDoubleCounted() external {
        _setupFeeDistributor();
        uint256 fee = 100_000_000; // divisible by 100, no dust
        vm.startPrank(vault);
        wbtc.approve(address(distributor), fee);
        distributor.accumulate(vault, fee);
        vm.stopPrank();
        distributor.distribute(vault);

        uint256 sumPools = distributor.pools(0) + distributor.pools(1) + distributor.pools(2);
        uint256 actual = wbtc.balanceOf(address(distributor));
        console2.log("sum(pools)      =", sumPools);      // 75_000_000
        console2.log("actual balance  =", actual);        // 50_000_000
        console2.log("overstatement   =", sumPools - actual); // 25_000_000 = gp(10M) + insurance(15M)
        assertGt(sumPools, actual);

        // gpEngine already received 10M in distribute() (line 136).
        // withdrawTo pays a SECOND 10M, funded out of the buyback pool's real balance.
        uint256 gpBefore = wbtc.balanceOf(gpEngine);
        vm.prank(governor);
        distributor.withdrawTo(gpEngine, fee * 10 / 100, 1);
        console2.log("gpEngine holds  =", wbtc.balanceOf(gpEngine)); // 20M for a 10M allocation
        assertEq(wbtc.balanceOf(gpEngine), gpBefore + fee * 10 / 100);
        assertEq(wbtc.balanceOf(gpEngine), fee * 20 / 100);

        // buyback pool accounting still says 50M but only 40M of real WBTC remains
        assertEq(distributor.pools(0), fee * 50 / 100);
        assertEq(wbtc.balanceOf(address(distributor))

